INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c4444444-4444-4444-4444-444444444444', 'Envase Plastico Con Valvula Cremera 1000 Ml', 'envase-plastico-con-valvula-cremera-1000-ml-73493', 'Envase Plástico con Válvula Cremera 1000 ml Solución Versátil para la Dosificación de Productos de Cuidado Personal El Envase Plástico con Válvula Cremera de 1000 ml es un insumo esencial para la organización y dosificación eficiente de productos líquidos viscosos en entornos corporativos e industriales. Su diseño ergonómico y la válvula de alta precisión facilitan la entrega controlada de jabones líquidos, geles antibacteriales o lociones, minimizando el desperdicio y manteniendo la higiene en estaciones de trabajo y áreas comunes. Fabricado con materiales resistentes, este envase de alta capacidad es ideal para procesos de reenvase, permitiendo a las empresas optimizar la compra de suministros a granel sin sacrificar la comodidad y presentación en sus instalaciones.', 1258.00, 20, 48, true, false, 'https://www.abastece.co/abastece/images/73493.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Envase Plastico Con Valvula Cremera 500 Ml', 'envase-plastico-con-valvula-cremera-500-ml-70578', 'Envase Plástico con Válvula Cremera 500 ml: Práctico y Versátil para tu Cocina Ideal para Salsas, Aderezos y Más Te presentamos el Envase Plástico con Válvula Cremera de 500 ml, diseñado para facilitar el uso y almacenamiento de tus salsas y aderezos favoritos. Su diseño con válvula permite un control preciso al verter, evitando derrames y asegurando una dosificación adecuada. Perfecto para la cocina, este envase es ideal para aliños, salsas, y otros líquidos. Además, su material plástico es ligero y duradero, lo que lo hace fácil de manejar y almacenar. ¡Optimiza tu experiencia culinaria con este práctico envase!', 1049.00, 20, 25, true, false, 'https://www.abastece.co/abastece/images/70578.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Envase Plastico Con Valvula Cremera De 120 Ml', 'envase-plastico-con-valvula-cremera-de-120-ml-75778', 'Envase Plástico con Válvula Cremera 1000 ml Solución Versátil para la Dosificación de Productos de Cuidado Personal El Envase Plástico con Válvula Cremera de 1000 ml es un insumo esencial para la organización y dosificación eficiente de productos líquidos viscosos en entornos corporativos e industriales. Su diseño ergonómico y la válvula de alta precisión facilitan la entrega controlada de jabones líquidos, geles antibacteriales o lociones, minimizando el desperdicio y manteniendo la higiene en estaciones de trabajo y áreas comunes. Fabricado con materiales resistentes, este envase de alta capacidad es ideal para procesos de reenvase, permitiendo a las empresas optimizar la compra de suministros a granel sin sacrificar la comodidad y presentación en sus instalaciones.', 883.00, 20, 29, true, false, 'https://www.abastece.co/abastece/images/75778.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Cerda Dura Con Mango De Madera 1.40m.', 'escoba-cerda-dura-con-mango-de-madera-140m-75874', 'Escoba de Cerda Dura con Mango de Madera (1.20 Mt) Herramienta de Limpieza de Alta Resistencia para Áreas Exteriores e Industriales La Escoba de Cerda Dura con Mango de Madera es el implemento esencial para las tareas de limpieza más exigentes en entornos industriales, bodegas y zonas exteriores. Sus cerdas rígidas están diseñadas para remover suciedad pesada, residuos sólidos y limpiar superficies rugosas con máxima eficiencia. Acompañada de un mango de madera de 1.20 metros que garantiza una postura ergonómica y mayor durabilidad bajo uso intensivo, esta herramienta es la elección predilecta de los equipos de servicios generales que buscan rendimiento y resistencia en el mantenimiento de plantas de producción, parqueaderos y áreas de alto tráfico.', 7221.00, 20, 15, true, false, 'https://www.abastece.co/abastece/images/75874.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Dura 1A Armonia Con Mango 120cm', 'escoba-dura-1a-armonia-con-mango-120cm-3514', 'Escoba Dura Armonía con Mango (120 cm) Marca 1A Limpieza Industrial Eficiente para Superficies Ásperas y Espacios Reducidos La Escoba Dura Armonía de la marca 1A es una herramienta de limpieza profesional diseñada para enfrentar los retos más exigentes en el mantenimiento de instalaciones. Sus fibras duras y altamente resistentes permiten una remoción profunda de suciedad en superficies ásperas, garantizando una limpieza impecable en bodegas, patios y áreas comunes. Con un mango de 120 cm que facilita la ergonomía durante el uso y un tamaño versátil que se adapta a espacios reducidos, esta escoba ofrece una durabilidad superior para el uso intensivo, convirtiéndose en un insumo clave para optimizar las tareas de aseo en entornos corporativos e industriales.', 7368.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/3514.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Dura 1A Armonia Sin Mango', 'escoba-dura-1a-armonia-sin-mango-3578', 'Escoba Dura Armonía Sin Mango Marca 1A: Eficiencia y Resistencia en Cada Barrida La Escoba Ideal para una Limpieza Rápida y Duradera La Escoba Dura Armonía Sin Mango Marca 1A es la herramienta perfecta para mantener tu hogar impecable. Con cerdas resistentes y de alta calidad, esta escoba es ideal para barrer tanto interiores como exteriores, eliminando polvo y suciedad de manera eficiente. Su diseño sin mango te permite adaptarla a cualquier tipo de mango estándar, dándote mayor comodidad en cada uso. Ya sea para la casa o el jardín, la Escoba Armonía es sinónimo de durabilidad y excelente rendimiento en todas tus tareas de limpieza.', 3888.00, 20, 52, true, false, 'https://www.abastece.co/abastece/images/3578.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Dura Fuller Pinto Girasol Con Mango Ref 810', 'escoba-dura-fuller-pinto-girasol-con-mango-ref-810-8354', 'Escoba Dura Girasol Con Mango Ref 810 – Fuller Pinto Potente limpieza y durabilidad en cada barrido La Escoba Dura Girasol con Mango Ref 810 de Fuller Pinto es ideal para una limpieza efectiva en superficies duras y rugosas. Sus cerdas firmes y resistentes permiten barrer polvo, suciedad y residuos con facilidad, mientras que el mango largo proporciona un agarre cómodo y ergonómico, reduciendo la fatiga durante el uso. Perfecta para áreas como patios, garajes, o cualquier espacio que requiera una limpieza profunda y duradera. Con su diseño robusto y duradero, esta escoba es una herramienta esencial para mantener tus espacios impecables. ¡Haz que tu limpieza sea más rápida y eficiente con la Escoba Dura Girasol Fuller Pinto!', 7924.00, 20, 32, true, false, 'https://www.abastece.co/abastece/images/8354.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Dura Fuller Pinto Girasol Sin Mango', 'escoba-dura-fuller-pinto-girasol-sin-mango-8970', 'Escoba Dura Girasol Sin Mango – Fuller Pinto Rendimiento superior en limpieza de superficies duras La Escoba Dura Girasol Sin Mango de Fuller Pinto es perfecta para una limpieza profunda y eficaz en espacios exteriores o superficies rugosas. Sus cerdas firmes y resistentes son ideales para barrer polvo, tierra y otros desechos de manera rápida y eficiente. Al no incluir mango, es compatible con cualquier mango estándar, brindándote la flexibilidad de personalizar su longitud según tus necesidades. Ideal para patios, jardines, garajes o almacenes, esta escoba es una herramienta esencial para mantener tus espacios limpios y ordenados. ¡Con la Escoba Dura Girasol Fuller Pinto, lograrás una limpieza más fácil y duradera!', 3818.00, 20, 18, true, false, 'https://www.abastece.co/abastece/images/8970.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Repuesto Melody De Fibra Extra Suave Polipropileno 25cm', 'escoba-repuesto-melody-de-fibra-extra-suave-polipropileno-25cm-75922', 'Escoba Repuesto Melody de Fibra Extra Suave (25 cm) Cuidado Superior para Pisos Delicados en Entornos Corporativos El Repuesto de Escoba Melody es la solución especializada para el mantenimiento de superficies que requieren un trato delicado, como madera laminada, mármol o porcelanato. Fabricada con fibras de polipropileno extra suaves de 25 cm, esta escoba garantiza una recolección eficiente de polvo y partículas finas sin rayar ni maltratar los acabados de sus pisos. Su diseño compacto y ligero facilita la limpieza en oficinas y áreas administrativas, permitiendo a los equipos de servicios generales optimizar el presupuesto mediante el reemplazo selectivo de cabezales, manteniendo siempre la máxima calidad en la presentación de sus instalaciones.', 11278.00, 20, 54, true, false, 'https://www.abastece.co/abastece/images/75922.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Repuesto Melody Suave Magica Amarilla', 'escoba-repuesto-melody-suave-magica-amarilla-74819', 'Escoba Repuesto Suave Mágica Melody Amarilla Eficiencia y cuidado para la limpieza de superficies delicadas La escoba repuesto suave Mágica Melody amarilla es un insumo técnico de alta calidad, diseñado específicamente para la remoción de polvo y partículas finas en superficies lisas y delicadas. Sus cerdas suaves y flexibles permiten un barrido eficiente sin rayar los acabados del piso, garantizando una limpieza profunda en cada pasada. Como producto de aseo institucional, esta referencia ofrece una durabilidad superior y una compatibilidad universal con mangos estándar, siendo la herramienta ideal para el mantenimiento diario de oficinas, consultorios y áreas comerciales que requieren un nivel de detalle y cuidado excepcional en su higiene.', 6691.00, 20, 26, true, false, 'https://www.abastece.co/abastece/images/74819.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Repuesto Melody Suave Magica Anaranjado', 'escoba-repuesto-melody-suave-magica-anaranjado-77156', 'Escoba Repuesto Suave Mágica Melody (Color Anaranjado) Máxima Eficiencia en Captura de Polvo para Ambientes Profesionales La Escoba Repuesto Suave Mágica Melody en color anaranjado es la solución técnica perfecta para el mantenimiento de pisos interiores que requieren un cuidado especial. Su tecnología de fibras &quot;mágicas&quot; de alta densidad permite atrapar partículas de polvo fino y suciedad ligera con una sola pasada, optimizando los tiempos de limpieza en oficinas, locales comerciales y consultorios. Este cabezal de repuesto ofrece una alternativa sostenible y rentable para las empresas, permitiendo mantener los implementos de aseo en condiciones óptimas sin necesidad de adquirir el equipo completo. Su vibrante color anaranjado facilita además la codificación por áreas, ayudando a prevenir la contaminación cruzada en sus protocolos de higiene institucional.', 6691.00, 20, 29, true, false, 'https://www.abastece.co/abastece/images/77156.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Repuesto Melody Suave Magica Blanca', 'escoba-repuesto-melody-suave-magica-blanca-77205', 'Escoba Repuesto Suave Mágica Melody Blanca · Unidad Reposición eficiente para superficies delicadas y limpieza constante Repuesto de escoba elaborado con fibras sintéticas suaves, diseñado para la recolección efectiva de polvo y residuos livianos en superficies lisas y sensibles. Su estructura flexible permite un barrido uniforme sin rayar ni levantar partículas, mientras el color blanco facilita la identificación visual y apoya procesos de estandarización y control higiénico. Compatible con bastones estándar, este insumo estratégico optimiza la continuidad operativa al simplificar reemplazos, extender la vida útil de los soportes existentes y mantener rutinas de limpieza ordenadas, contribuyendo al bienestar del equipo y a una gestión logística eficiente.', 6691.00, 20, 16, true, false, 'https://www.abastece.co/abastece/images/77205.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Repuesto Melody Suave Magica Negro', 'escoba-repuesto-melody-suave-magica-negro-74821', 'Escoba Repuesto Suave Mágica Melody (Color Negro) Especialista en Captura de Polvo Fino para Áreas Administrativas La Escoba Repuesto Suave Mágica Melody en color negro es la herramienta de precisión ideal para el mantenimiento de oficinas y espacios interiores con altos estándares de limpieza. Su tecnología de fibras suaves &quot;mágicas&quot; está diseñada para atraer y capturar el polvo más fino, evitando que las partículas se dispersen en el aire durante el barrido. Gracias a su cabezal de repuesto, las organizaciones pueden renovar sus implementos de aseo de forma sostenible y económica, asegurando que los pisos de recepciones, salas de juntas y despachos mantengan un brillo impecable sin riesgo de rayaduras. Es la opción preferida para superficies de mármol, baldosa lacada y laminados.', 6691.00, 20, 20, true, false, 'https://www.abastece.co/abastece/images/74821.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Repuesto Melody Suave Magica Roja', 'escoba-repuesto-melody-suave-magica-roja-77574', 'Escoba Repuesto Melody Suave Magica Roja ¡Optimice las rutinas de barrido en interiores, proteja sus pisos delicados y garantice la máxima pulcritud en sus instalaciones! Asegure una remoción eficiente de polvo, pelusas y partículas finas sin rayar ni maltratar las superficies lisas de sus oficinas, preserve el estado de sus pisos de baldosa, madera o laminado y mantenga una imagen impecable en cada espacio corporativo. El uso del escoba repuesto melody suave magica roja facilita la estandarización de procesos de aseo y código de colores en la compañía, unificando los insumos de mantenimiento preventivo e higiene institucional según las distintas áreas de trabajo. Sus cerdas suaves de alta densidad y rosca universal aseguran la continuidad operativa durante las jornadas de servicios generales, permitiendo un acople rápido a los cabos existentes y prolongando la vida útil del equipo de limpieza sin interrumpir las labores diarias. Incorpore este repuesto a sus existencias para elevar la eficiencia logística en las compras de insumos e implementos de aseo empresarial, impulsando el bienestar del equipo al suministrar herramientas ergonómicas, livianas y funcionales para el personal operativo.', 6691.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/77574.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Repuesto Melody Suave Magica Verde', 'escoba-repuesto-melody-suave-magica-verde-74820', 'Escoba Repuesto Suave Mágica Melody Verde Limpieza Eficiente de Polvo Fino y Codificación por Áreas La Escoba Repuesto Melody Verde está diseñada para la limpieza de interiores y pisos delicados. Sus fibras suaves atrapan el polvo fino sin rayar superficies como baldosa o laminados. Su color verde facilita el cumplimiento de protocolos de higiene mediante la codificación por zonas (como áreas de alimentos o cafeterías), optimizando el gasto al permitir el recambio del cabezal sin cambiar el mango.', 6691.00, 20, 45, true, false, 'https://www.abastece.co/abastece/images/74820.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Repuesto Suave Mega Cristal Morada', 'escoba-repuesto-suave-mega-cristal-morada-4111', 'Escoba Repuesto Suave Mega Cristal Morada · Unidad Reposición ágil para rutinas de limpieza bien coordinadas Repuesto de escoba elaborado con fibras sintéticas suaves, orientado a la recolección eficiente de polvo y partículas finas en superficies lisas. Su diseño flexible favorece un barrido uniforme sin deteriorar el piso, mientras el acabado cristal en color morado contribuye a la diferenciación visual y a la estandarización de insumos de aseo. Compatible con bastones de medida estándar, permite optimizar la continuidad operativa al facilitar reemplazos rápidos, mantener stock funcional y asegurar condiciones de limpieza consistentes que favorecen el bienestar del equipo y la eficiencia logística.', 6283.00, 20, 54, true, false, 'https://www.abastece.co/abastece/images/4111.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Repuesto Suave WM Suprema Premium Color Surtido.', 'escoba-repuesto-suave-wm-suprema-premium-color-surtido-77700', 'Escoba Repuesto Suave WM Suprema Premium Color Surtido ¡Barra sin rayar, remueva el polvo más fino y mantenga sus pisos impecables! Mantenga las delicadas superficies de su hogar u oficina libres de polvo y suciedad con el repuesto de escoba suave WM Suprema Premium. Diseñada con cerdas ultrasuaves de alta calidad, atrapa de manera eficiente las partículas finas, pelusas y residuos sin maltratar ni rayar pisos de madera, laminado, cerámica o porcelanato. Su estructura resistente se adapta a mangos estándar, ofreciendo una larga vida útil y un barrido ágil y liviano en color surtido. ¡Pida el suyo hoy y cuide la apariencia de sus pisos con total efectividad!', 4508.00, 20, 52, true, false, 'https://www.abastece.co/abastece/images/77700.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Suave 1A Armonia Con Mango 120cm', 'escoba-suave-1a-armonia-con-mango-120cm-3577', 'Escoba Suave Armonía con Mango 120 cm Marca 1A: Comodidad y Eficiencia en tu Limpieza Diaria La Escoba Perfecta para Barrer con Facilidad y Sin Esfuerzo La Escoba Suave Armonía con Mango 120 cm Marca 1A es la herramienta ideal para barrer superficies delicadas y mantener tu hogar limpio con comodidad. Con cerdas suaves y un mango de 120 cm, esta escoba permite un barrido eficiente sin rayar o dañar los pisos. Su diseño ergonómico te ofrece mayor control y facilita la limpieza sin tener que inclinarte. Perfecta para el uso en interiores, es ideal para pisos de madera, cerámica o vinil. ¡Haz que la limpieza diaria sea más fácil y cómoda con la Escoba Armonía!', 7439.00, 20, 17, true, false, 'https://www.abastece.co/abastece/images/3577.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Suave 1A Armonia Sin Mango', 'escoba-suave-1a-armonia-sin-mango-3576', '-Escoba de fibras suaves, resistentes y plumillada -Limpieza eficiente de los espacios -Alta durabilidad -Tamaño que se adapta a espacios pequeños', 3946.00, 20, 22, true, false, 'https://www.abastece.co/abastece/images/3576.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Suave Fuller Pinto Orquidea Con Mango Ref 810', 'escoba-suave-fuller-pinto-orquidea-con-mango-ref-810-1781', 'Escoba Suave Orquidea con Mango Ref 810 Fuller Pinto La Solucion Perfecta para una Limpieza Eficiente Presentamos la escoba suave Orquidea con mango, referencia 810 de Fuller Pinto. Diseñada para ofrecer una limpieza efectiva en todo tipo de superficies, su suave material permite barrer con facilidad sin rayar ni dañar. Ideal para el hogar, oficinas o espacios comerciales, su mango ergonomico proporciona un agarre comodo, facilitando el uso prolongado. ¡Haz que la limpieza sea un placer con la escoba suave Orquidea!', 8393.00, 20, 17, true, false, 'https://www.abastece.co/abastece/images/1781.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Suave Fuller Pinto Sin Mango Ref 218', 'escoba-suave-fuller-pinto-sin-mango-ref-218-9504', 'Escoba Suave Sin Mango Ref 218 - Fuller Pinto Limpieza Eficiente y Práctica para tu Hogar Descubre la Escoba Suave Sin Mango Ref 218 de Fuller Pinto, diseñada para facilitar la limpieza de cualquier superficie. Su fibra suave atrapa el polvo y la suciedad de manera efectiva, ideal para pisos delicados y áreas de difícil acceso. Compacta y ligera, esta escoba es perfecta para mantener tu hogar impecable sin complicaciones. ¡Haz de la limpieza una tarea rápida y sencilla!', 8782.00, 20, 24, true, false, 'https://www.abastece.co/abastece/images/9504.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Suave Melody Con Mango Rojo 1.50cm', 'escoba-suave-melody-con-mango-rojo-150cm-76498', 'Escoba Suave Melody Roja con Mango (1.50 mt) Limpieza Delicada y Ergonómica para Interiores Corporativos La Escoba Suave Melody Roja es la herramienta ideal para el mantenimiento de pisos delicados en oficinas y áreas administrativas. Sus fibras suaves permiten capturar el polvo fino sin rayar superficies como madera laminada o porcelanato. Incluye un mango de 1.50 metros que mejora la ergonomía del operario, reduciendo la fatiga. Su color rojo facilita la codificación de áreas en planes de saneamiento institucional, asegurando un entorno limpio y profesional.', 30200.00, 20, 45, true, false, 'https://www.abastece.co/abastece/images/76498.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Escoba Suave Premium Ref 12138 Con Mango Metalico 150 Cm Ref: 105817', 'escoba-suave-premium-ref-12138-con-mango-metalico-150-cm-ref-105817-76120', 'Escoba Suave Premium con Mango Metálico (150 cm) Resistencia y Cuidado Superior para Superficies de Alto Tráfico La Escoba Suave Premium es la solución de alta gama para el mantenimiento de pisos delicados en entornos corporativos. Su cabezal de fibras suaves garantiza una limpieza efectiva de polvo fino sin rayar superficies de mármol o porcelanato. Equipada con un robusto mango metálico de 1.50 metros, ofrece una durabilidad excepcional frente al uso intensivo y una ergonomía superior para el operario, optimizando las jornadas de limpieza en grandes oficinas y áreas comerciales.', 17677.00, 20, 22, true, false, 'https://www.abastece.co/abastece/images/76120.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja Bon Bril Borrador Magico', 'esponja-bon-bril-borrador-magico-3662', 'Esponja Borrador MÃƒ¡gico Bon Bril Ã¢â‚¬- Por Unidad Elimina manchas y marcas fÃƒ¡cilmente con solo un toque La Esponja Borrador MÃƒ¡gico Bon Bril es la herramienta perfecta para eliminar manchas, marcas y suciedad sin esfuerzo. Su diseÃƒÂ±o innovador utiliza una tecnologia de microfibra que actua como una goma de borrar, eliminando todo tipo de residuos y manchas en paredes, superficies de cocina, baÃƒÂ±o, y mÃƒ¡s. No requiere productos quimicos adicionales, lo que la convierte en una opcion ecologica y segura para el hogar. Su tamaÃƒÂ±o compacto y presentacion por unidad la hace ideal para tener siempre a mano cuando la necesites. Ã‚¡Haz que tus superficies luzcan como nuevas con la Esponja Borrador MÃƒ¡gico Bon Bril!', 4030.00, 20, 52, true, false, 'https://www.abastece.co/abastece/images/3662.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja De Alambre Galvanizada Paquete X3 Task', 'esponja-de-alambre-galvanizada-paquete-x3-task-3936', 'Esponja de Alambre Galvanizada Task (Paquete x3) Limpieza Profunda y Remoción de Suciedad Difícil en Cocinas Industriales La Esponja de Alambre Galvanizada Task es la herramienta de alto poder abrasivo indispensable para la limpieza pesada en cafeterías y áreas de cocina corporativas. Su estructura de alambre galvanizado permite remover grasa quemada, sarro y residuos incrustados en superficies metálicas, ollas y parrillas sin desintegrarse. Este paquete por 3 unidades ofrece un rendimiento superior y durabilidad, asegurando que los equipos de servicios generales cuenten con el insumo necesario para mantener los estándares de higiene en entornos de uso intensivo.', 2185.00, 20, 17, true, false, 'https://www.abastece.co/abastece/images/3936.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja De Alambre Por Unidad', 'esponja-de-alambre-por-unidad-1782', 'Esponja de Alambre - Limpieza Eficiente por Unidad La Solución Ideal para tus Necesidades de Limpieza Descubre nuestra Esponja de Alambre, diseñada para ofrecer una limpieza profunda y efectiva en todo tipo de superficies. Perfecta para eliminar grasa y residuos difíciles, esta esponja es un aliado indispensable en tu hogar o cocina. Disponible por unidad, es práctica y fácil de usar, garantizando resultados impecables en cada uso.', 341.00, 20, 20, true, false, 'https://www.abastece.co/abastece/images/1782.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja Doble Uso Amarillo / Verde Scotch Britte Pague 8 Lleve 12u.', 'esponja-doble-uso-amarillo-verde-scotch-britte-pague-8-lleve-12u-77431', 'Esponja Doble Uso Amarillo / Verde Scotch Brite Pague 8 Lleve 12u. ¡Optimice las rutinas de aseo con un suministro de alta rotación, máximo rendimiento y ahorro institucional! Maximice la eficiencia en las tareas de mantenimiento y limpieza de las instalaciones de su empresa con este kit de aseo de amplio reconocimiento. La implementación de la esponja doble uso amarillo / verde Scotch Brite pague 8 lleve 12u. facilita la estandarización de procesos de desinfección e higiene en cafeterías, casinos, áreas comunes o de producción, permitiendo unificar los métodos de lavado bajo un estándar que cuida las superficies y remueve la suciedad de manera efectiva. Su presentación en paquete múltiple asegura la continuidad operativa de su personal de servicios generales, garantizando un stock de reserva confiable que evita interrupciones o compras imprevistas en el día a día de la organización. Adquiera este paquete promocional hoy mismo para mejorar la eficiencia logística de sus compras de inventario y suministros de limpieza con una excelente relación costo-beneficio, potenciando el bienestar del equipo al proveer herramientas que facilitan las labores de orden y aseo, manteniendo un entorno de trabajo impecable, saludable y profesional.', 11947.00, 20, 43, true, false, 'https://www.abastece.co/abastece/images/77431.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja Doble Uso Eterna', 'esponja-doble-uso-eterna-1861', 'Esponja Doble Uso Eterna por Unidad Versatilidad y Eficiencia en un Solo Producto La Esponja Doble Uso Eterna por Unidad es la herramienta perfecta para todo tipo de limpieza. Su diseño innovador permite utilizarla en ambas caras: una suave para superficies delicadas y otra más áspera para suciedad difícil. Ideal para el hogar, la cocina o el baño, esta esponja garantiza una limpieza eficaz y duradera, sin dañar tus superficies. Apuesta por la calidad y versatilidad de la Esponja Eterna para tus tareas diarias.', 666.00, 20, 22, true, false, 'https://www.abastece.co/abastece/images/1861.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja Espiral Metalica Inoxidable Eterna', 'esponja-espiral-metalica-inoxidable-eterna-3834', 'Esponja Espiral Metálica Inoxidable Eterna por Unidad La esponja ideal para limpieza eficiente y duradera La Esponja Espiral Metálica Inoxidable Eterna por Unidad es perfecta para eliminar residuos difíciles sin dañar superficies. Su diseño espiral y su material de acero inoxidable garantizan una larga vida útil y un rendimiento excepcional en tareas de limpieza. Ideal para uso en cocina, talleres y áreas de alto tránsito, ofreciendo una solución eficaz y duradera para tus necesidades de limpieza.', 2562.00, 20, 44, true, false, 'https://www.abastece.co/abastece/images/3834.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja Espiral Metalica Inoxidable Scotch Brite Por Unidad', 'esponja-espiral-metalica-inoxidable-scotch-brite-por-unidad-3110', '¡Limpieza eficiente para tu hogar o industria! Esponja Espiral Metálica Inoxidable Scotch Brite - por Unidad Esponja espiral metálica de acero inoxidable Scotch Brite, ideal para limpiar utensilios, superficies y equipos con suciedad difícil. Producto duradero y resistente para uso diario.', 2828.00, 20, 51, true, false, 'https://www.abastece.co/abastece/images/3110.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja Espiral Metalica Inoxidable Scotch Brite X2u.', 'esponja-espiral-metalica-inoxidable-scotch-brite-x2u-3879', 'Esponja Espiral Metálica Inoxidable Scotch-Brite (Pack x2) Máxima Abrasión y Resistencia para Limpieza Pesada Industrial La Esponja Metálica Scotch-Brite es el estándar en limpieza profunda para cocinas industriales y casinos de empresas. Fabricada en acero inoxidable de alta calidad, su diseño en espiral permite remover grasa adherida y residuos difíciles sin oxidarse ni soltar partículas metálicas. Este paquete por 2 unidades garantiza un rendimiento superior en superficies de acero, ollas y parrillas, ofreciendo una herramienta duradera que facilita las labores del personal de servicios generales en entornos de alta exigencia.', 4049.00, 20, 32, true, false, 'https://www.abastece.co/abastece/images/3879.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja Eterna Oro Y Plata Pague 2 Lleve 3', 'esponja-eterna-oro-y-plata-pague-2-lleve-3-75728', 'Esponja Eterna Oro y Plata (Pack x3 Unidades) Limpieza Delicada y Antirrayas para Superficies Especiales La Esponja Eterna Oro y Plata es la solución ideal para el mantenimiento de artículos delicados en cafeterías y oficinas. Su textura suave está diseñada para limpiar superficies críticas como teflón, acero inoxidable, cristalería y vajilla fina sin dejar rayones. Este pack promocional de 3 unidades permite optimizar el inventario de aseo, garantizando que el personal de servicios generales cuente con herramientas seguras para proteger la vida útil de los utensilios de cocina corporativos.', 5705.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/75728.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja Inox Eterna Pague 2 Lleve 4', 'esponja-inox-eterna-pague-2-lleve-4-75798', 'Esponja Inox Eterna (Pack x4 Unidades) Limpieza Pesada de Alto Rendimiento para Cocinas Industriales La Esponja Inox Eterna es la herramienta definitiva para la remoción de suciedad difícil en entornos de cocina profesional. Fabricada en acero inoxidable de alta calidad, resiste la oxidación y mantiene su forma incluso bajo uso intensivo. Este pack promocional de 4 unidades es ideal para empresas que buscan optimizar costos en insumos de aseo sin sacrificar eficiencia, permitiendo eliminar grasa rebelde y residuos quemados de ollas, parrillas y superficies metálicas con el mínimo esfuerzo.', 7049.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/75798.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja Multiusos Brillo Inoxidable Pinto Por Unidad', 'esponja-multiusos-brillo-inoxidable-pinto-por-unidad-76470', 'Esponja Multiusos Brillo Inoxidable Pinto Remoción de Suciedad Difícil y Brillo para Superficies Metálicas La Esponja Multiusos Brillo Inoxidable Pinto es una herramienta técnica esencial para la limpieza profunda en cocinas y casinos industriales. Su estructura abrasiva permite eliminar grasa acumulada y residuos difíciles en utensilios de acero inoxidable, ollas y parrillas sin maltratar las superficies metálicas. Diseñada para ofrecer una larga vida útil en entornos de uso intensivo, esta esponja garantiza un acabado impecable, siendo un insumo clave para los equipos de servicios generales que buscan eficiencia y durabilidad en el mantenimiento de equipos de cocina.', 3587.00, 20, 24, true, false, 'https://www.abastece.co/abastece/images/76470.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja Multiusos Suave Malla Blanca Paq X 2 Unidades', 'esponja-multiusos-suave-malla-blanca-paq-x-2-unidades-3685', 'Esponja Multiusos Suave Malla Blanca Paquete x 2 Unidades Practicidad y suavidad para una limpieza efectiva en cualquier superficie La **Esponja Multiusos Suave Malla Blanca** es perfecta para realizar tareas de limpieza diarias sin dañar las superficies. Su diseño de malla blanca la hace suave, pero a la vez resistente, permitiendo limpiar con eficacia sin rayar ni dejar marcas. Ideal para usar en cocinas, baños, vidrios y más, esta esponja proporciona un rendimiento superior en limpieza y eliminación de grasa, suciedad y residuos. El paquete incluye 2 unidades, brindándote una excelente relación calidad-precio y mayor durabilidad para tus necesidades de limpieza. ¡Mantén tus espacios impecables con esta práctica esponja multiusos!', 1777.00, 20, 16, true, false, 'https://www.abastece.co/abastece/images/3685.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponja Multiusos Suave Malla Piurex Paq.x2u.', 'esponja-multiusos-suave-malla-piurex-paqx2u-5145', 'Esponja Multiusos Suave Malla Piurex Paq x 2 Unidades: Eficiencia y Suavidad para tu Limpieza Diaria La Solucion Perfecta para una Limpieza Suave y Eficaz Las Esponjas Multiusos Suaves Malla Piurex, en paquete de 2 unidades, son ideales para realizar todo tipo de limpieza sin dañar superficies delicadas. Su diseño de malla y suavidad permite una limpieza eficaz en cocina, baño y otras areas de tu hogar, removiendo la suciedad con facilidad mientras cuidan tus superficies. ¡Haz que tu limpieza diaria sea mas eficiente y suave con las esponjas Piurex!', 2282.00, 20, 54, true, false, 'https://www.abastece.co/abastece/images/5145.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Esponjilla Bon Bril Paq.x 12u.', 'esponjilla-bon-bril-paqx-12u-2039', 'Esponjilla Bon Bril: Limpieza eficiente para ollas relucientes Descubre la potencia de la limpieza Brillo impecable para tus utensilios de cocina Con la Esponjilla Bon Bril Brilla Ollas, tu cocina brillará. Elimina grasa y residuos con facilidad, preservando la calidad de tus ollas. ¡Experimenta el brillo deslumbrante en cada uso!', 3806.00, 20, 37, true, false, 'https://www.abastece.co/abastece/images/2039.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Fabuloso Limpiador Multiusos Antibacterial 2 Lts Aroma Bebe', 'fabuloso-limpiador-multiusos-antibacterial-2-lts-aroma-bebe-8247', 'Limpiador Multiusos con Aroma Fresco para tus espacios limpios y saludables Elimina gérmenes y disfruta de un ambiente aromatizado unico en cada rincón Ideal para mantener tu hogar y oficina libre de bacterias y con un agradable aroma fresco. Su fórmula avanzada combate eficazmente los gérmenes y deja una sensación de limpieza duradera en cocinas, baños y otros espacios', 11912.00, 20, 53, true, false, 'https://www.abastece.co/abastece/images/8247.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Fibra Limpiadora Eterna Verde', 'fibra-limpiadora-eterna-verde-1713', 'Fibra Limpiadora Eterna Verde por Unidad Fuerza y eficiencia en cada limpieza La **Fibra Limpiadora Eterna Verde** es la opción ideal para eliminar la suciedad y las manchas más difíciles. Con su textura abrasiva y resistente, es perfecta para la limpieza de superficies de cocina, baños y otros espacios del hogar. Su color verde y material duradero aseguran una limpieza eficaz sin dañar las superficies. La **Fibra Limpiadora Eterna** es fácil de usar y se mantiene en excelente estado durante mucho tiempo, lo que la convierte en una herramienta esencial en tu hogar o lugar de trabajo. ¡Obtén resultados de limpieza excepcionales con la **Fibra Limpiadora Eterna Verde**!', 676.00, 20, 24, true, false, 'https://www.abastece.co/abastece/images/1713.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Fibra Para Limpieza Trabajo Pesado Eterna X2u.', 'fibra-para-limpieza-trabajo-pesado-eterna-x2u-3835', 'Fibra para Limpieza Trabajo Pesado Eterna x2u La solucion perfecta para limpieza de alta resistencia La Fibra para Limpieza Trabajo Pesado Eterna x2u estÃƒ¡ diseÃƒÂ±ada para enfrentar las tareas de limpieza mÃƒ¡s exigentes. Con su durabilidad y resistencia, esta fibra es ideal para eliminar suciedad y grasa en superficies dificiles sin perder eficacia. Perfecta para trabajos industriales, talleres y Ãƒ¡reas con suciedad incrustada, ofreciendo un rendimiento superior y largo tiempo de uso.', 1486.00, 20, 53, true, false, 'https://www.abastece.co/abastece/images/3835.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Fibra Scotch Brite De Limpieza Clasica Verde', 'fibra-scotch-brite-de-limpieza-clasica-verde-3468', 'Fibra de Limpieza Clásica Scotch-Brite Verde Poder Abrasivo Superior para Aseo Industrial y de Cafetería La Fibra Verde Scotch-Brite es el estándar en limpieza profunda para cocinas corporativas y entornos industriales. Su malla abrasiva de alta resistencia está diseñada para remover grasa pegada y residuos difíciles en superficies que no requieren cuidados delicados, como ollas de aluminio, parrillas y utensilios de cocina pesados. Gracias a su durabilidad y resistencia a los químicos de limpieza, esta fibra por unidad ofrece un rendimiento prolongado, ayudando a los equipos de servicios generales a mantener los niveles más altos de higiene con el menor esfuerzo.', 17690.00, 20, 17, true, false, 'https://www.abastece.co/abastece/images/3468.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Fibra Scotch Brite La Maquina Trabajo Pesado', 'fibra-scotch-brite-la-maquina-trabajo-pesado-3456', 'Fibra La Maquina Trabajo Pesado Scotch Brite: ¡Potencia en Cada Fibras! Ideal para las Tareas Mas Exigentes de Limpieza Descubre la Fibra La Maquina Trabajo Pesado Scotch Brite, diseñada para enfrentar las tareas mas dificiles con facilidad. Su robusta textura elimina la grasa y la suciedad mas adherida sin dañar las superficies. Perfecta para uso en cocinas, talleres y mas, esta fibra es tu aliada para lograr una limpieza profunda y eficaz. ¡Potencia y durabilidad en un solo producto!', 1278.00, 20, 15, true, false, 'https://www.abastece.co/abastece/images/3456.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Fibra Scotch Brite La Maquina Trabajo Pesado x3', 'fibra-scotch-brite-la-maquina-trabajo-pesado-x3-3827', 'Fibra La Máquina Trabajo Pesado Scotch Brite – 3 Unidades Fuerza y durabilidad para limpiar superficies difíciles La Fibra La Máquina Trabajo Pesado Scotch Brite, en presentación de 3 unidades, es la herramienta perfecta para realizar tareas de limpieza intensiva. Ideal para superficies difíciles, como parrillas, hornos, utensilios de cocina y más, su abrasividad de alta resistencia elimina fácilmente suciedades, grasa y residuos difíciles sin dañar las superficies. Estas fibras están diseñadas para trabajos pesados, proporcionando una limpieza profunda y eficaz. Su durabilidad asegura un rendimiento prolongado, incluso en condiciones de uso intenso. ¡Logra resultados impecables con la Fibra La Máquina Scotch Brite, la mejor opción para limpieza profesional!', 3522.00, 20, 40, true, false, 'https://www.abastece.co/abastece/images/3827.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Gancho Industrial 1A  Metalico Con Mango Para Mecha Tipo Cosida 150cm', 'gancho-industrial-1a-metalico-con-mango-para-mecha-tipo-cosida-150cm-2113', 'Gancho Industrial Metálico de 150 cm con Mango (Marca 1A) Soporte de Alta Resistencia para Mechas de Trapero Tipo Cosida El Gancho Industrial Metálico Marca 1A es un componente robusto diseñado para el mantenimiento profesional de pisos en áreas de alto tráfico. Fabricado con materiales resistentes a la oxidación, este sistema de sujeción es ideal para el uso diario con mechas de trapero tipo cosida. Su mango de 150 cm proporciona el alcance y la ergonomía necesarios para optimizar las jornadas de limpieza en bodegas, plantas de producción y grandes superficies, asegurando una fijación segura y una larga vida útil bajo condiciones de trabajo pesado.', 21566.00, 20, 51, true, false, 'https://www.abastece.co/abastece/images/2113.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Ganchos Plasticos Negros Para Ropa Paq.x100u.', 'ganchos-plasticos-negros-para-ropa-paqx100u-75240', 'Ganchos Plásticos Negros para Ropa (Paquete x 100) Solución de Organización para Dotaciones, Hotelería y Comercio El Paquete de Ganchos Plásticos Negros ofrece una solución eficiente y económica para la organización de prendas en entornos corporativos, comerciales e institucionales. Fabricados en polipropileno de alta resistencia, estos ganchos están diseñados para soportar el uso continuo en áreas de dotación de personal, vestidores industriales o servicios de hotelería. Su acabado en color negro proporciona una estética uniforme y profesional, mientras que el formato mayorista de 100 unidades asegura un abastecimiento constante para la gestión de inventarios de ropa y uniformes.', 34143.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/75240.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Germicida Cuaternario Neutro 1000 Ml', 'germicida-cuaternario-neutro-1000-ml-3678', 'Germicida Cuaternario Neutro (1000 ml) Desinfección de Alto Nivel para Superficies Clínicas e Industriales El Germicida Cuaternario Neutro es un desinfectante concentrado diseñado para eliminar microorganismos en entornos que exigen máximos estándares de higiene, como laboratorios, consultorios y plantas de procesamiento. Su fórmula basada en amonios cuaternarios garantiza una acción bactericida y fungicida eficaz sin ser corrosiva, lo que lo hace seguro para superficies metálicas, plásticas y equipos delicados. Con una presentación de 1000 ml, es la solución técnica ideal para protocolos de bioseguridad institucional, permitiendo una desinfección profunda con un pH neutro que protege la integridad de los materiales tratados.', 4116.00, 20, 33, true, false, 'https://www.abastece.co/abastece/images/3678.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Algodon Blanco Talla 9', 'guante-algodon-blanco-talla-9-75513', 'Guante de Algodón Blanco Talla 9 x Par Protección ligera que optimiza el confort en el trabajo diario Guantes en algodón blanco talla 9, fabricados en material suave, transpirable y reutilizable que proporciona comodidad durante el uso prolongado. Su diseño ergonómico permite un ajuste adecuado y buena movilidad, favoreciendo la estandarización en tareas de manipulación ligera y aportando a la continuidad operativa mediante un insumo estratégico que optimiza la protección básica de las manos y mejora el desempeño en actividades generales.', 2965.00, 20, 51, true, false, 'https://www.abastece.co/abastece/images/75513.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Color Rosado Calibre 18 Talla 8', 'guante-color-rosado-calibre-18-talla-8-76213', 'Guante de Látex Rosado Calibre 18 (Talla 8) Protección y Resistencia para Labores de Limpieza Institucional El Guante de Látex Calibre 18 es un elemento de protección personal indispensable para operarios de aseo en entornos corporativos y comerciales. Su calibre 18 ofrece un equilibrio ideal entre sensibilidad táctil y alta resistencia ante productos químicos de limpieza, detergentes y humedad. Diseñado en un distintivo color rosado, facilita la codificación de tareas por áreas para evitar la contaminación cruzada. Su horma ergonómica en talla 8 asegura comodidad durante jornadas prolongadas, protegiendo la piel de irritaciones y asegurando un agarre firme en superficies húmedas o resbaladizas.', 4957.00, 20, 31, true, false, 'https://www.abastece.co/abastece/images/76213.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante De Caucho Calibre 18 Fuller Pinto Azul Talla M', 'guante-de-caucho-calibre-18-fuller-pinto-azul-talla-m-75375', 'Guante de Caucho Fuller Pinto Azul (Calibre 18 - Talla M) Protección Versátil y Confort para el Mantenimiento Institucional El Guante de Caucho Fuller Pinto en calibre 18 es una solución equilibrada para la protección de manos en tareas de limpieza profesional y manipulación de insumos de cafetería. Su diseño en color azul facilita el cumplimiento de normativas de higiene y seguridad mediante la segregación por áreas. Fabricado con un látex flexible, este guante en talla M ofrece un ajuste ergonómico que reduce la fatiga manual, proporcionando una barrera efectiva contra detergentes y agentes líquidos sin perder la sensibilidad táctil necesaria para el manejo de utensilios y superficies.', 4709.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/75375.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante De Caucho Calibre 18 Fuller Pinto Azul Talla S', 'guante-de-caucho-calibre-18-fuller-pinto-azul-talla-s-77814', 'Guante De Caucho Calibre 18 Fuller Pinto Azul Talla S ¡Protección de grado industrial, calibre 18 reforzado y labrado antideslizante para manipulación segura de químicos e insumos de aseo! Asegure la máxima protección del personal operativo en labores de limpieza exigentes y manipulación química con el Guante de Caucho Calibre 18 Fuller Pinto en color azul y talla S (pequeña). Fabricado en látex de caucho natural vulcanizado de calibre pesado 18, este guante de seguridad industrial ofrece una barrera física de alta resistencia contra la abrasión, desgarres, punciones leves y contacto prolongado con detergentes, desinfectantes, soluciones ácidas suaves y álcalis. Su diseño ergonómico de caña alta con orillo enrollado previene el goteo hacia la manga, mientras que su grabado antideslizante en la palma y yema de los dedos garantiza un agarre firme tanto en superficies secas como húmedas. Es un elemento de protección personal (EPP) de alta rotación e indispensable para empresas de servicios generales de aseo, laboratorios, plantas de procesamiento de alimentos, sector HORECA, talleres y mantenimiento institucional. ¡Doté a sus colaboradores con EPP industrial de alta calidad y reduzca los riesgos de bioseguridad en sus instalaciones!', 4709.00, 20, 45, true, false, 'https://www.abastece.co/abastece/images/77814.jpg')
INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c4444444-4444-4444-4444-444444444444', 'Guante Domestico Amarillo Calibre 18 Talla 7 - 7.5', 'guante-domestico-amarillo-calibre-18-talla-7-75-3525', 'Guante Doméstico Amarillo Calibre 18 Talla 7-7.5 Protección y Comodidad para Tareas Domésticas y de Limpieza El Guante Doméstico Amarillo Calibre 18 Talla 7-7.5 está diseñado para ofrecer una protección ideal en tareas de limpieza y trabajos domésticos. Con un calibre 18, estos guantes proporcionan resistencia contra detergentes, productos químicos suaves y suciedad, garantizando que tus manos estén protegidas durante todo el proceso. Su ajuste cómodo para la talla 7-7.5 asegura un uso prolongado sin incomodidad, permitiendo destreza y flexibilidad al realizar tareas cotidianas como lavar platos, limpiar superficies o manipular objetos mojados. Perfectos para quienes buscan guantes duraderos, cómodos y resistentes para el hogar.', 3285.00, 20, 15, true, false, 'https://www.abastece.co/abastece/images/3525.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Domestico Amarillo Calibre 18 Talla 8 - 8.5', 'guante-domestico-amarillo-calibre-18-talla-8-85-3527', 'Guante Domestico Amarillo Calibre 18 Talla 8-8.5 Comodidad y Proteccion para Tareas Domesticas y de Limpieza El Guante Domestico Amarillo Calibre 18 Talla 8-8.5 esta diseñado para brindar una proteccion eficiente y comodidad en tareas de limpieza y trabajos domesticos. Con un calibre 18, estos guantes ofrecen resistencia a productos de limpieza y sustancias domesticas, protegiendo tus manos de detergentes y humedad. Su diseño ergonomico y su ajuste perfecto para la talla 8-8.5 garantizan un uso prolongado sin incomodidad, permitiendo una alta destreza durante tareas como lavar platos, limpiar superficies o manipular objetos mojados. Ideal para quienes buscan un guante comodo, flexible y duradero para el hogar.', 3285.00, 20, 26, true, false, 'https://www.abastece.co/abastece/images/3527.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Domestico Amarillo Calibre 18 Talla 8 Fuller Pinto', 'guante-domestico-amarillo-calibre-18-talla-8-fuller-pinto-73395', 'Guante Doméstico Amarillo Fuller Pinto (Calibre 18 - Talla 8) Protección Fiable y Flexibilidad para Tareas de Limpieza General El Guante Doméstico Fuller Pinto es la herramienta de protección esencial para servicios generales y mantenimiento en oficinas. Su calibre 18 ofrece una resistencia óptima contra detergentes y humedad, manteniendo la flexibilidad necesaria para un manejo seguro de utensilios. El color amarillo permite una fácil identificación visual para protocolos de aseo estándar. Gracias a su diseño ergonómico en talla 8, garantiza comodidad y un agarre antideslizante superior en superficies mojadas, protegiendo eficazmente las manos del personal operativo.', 4725.00, 20, 18, true, false, 'https://www.abastece.co/abastece/images/73395.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Domestico Amarillo Calibre 18 Talla 9 - 9.5', 'guante-domestico-amarillo-calibre-18-talla-9-95-3529', 'Guante Doméstico Amarillo Calibre 18 Talla 9-9.5 Protección y Comodidad para el Hogar y Tareas de Limpieza El Guante Doméstico Amarillo Calibre 18 Talla 9-9.5 está diseñado para ofrecer la mejor protección y comodidad durante tareas domésticas y de limpieza. Con un calibre 18, estos guantes son resistentes a productos de limpieza, detergentes y agua, protegiendo tus manos de posibles irritaciones o daños. Su ajuste para la talla 9-9.5 asegura una gran comodidad durante el uso prolongado, permitiendo realizar tareas como lavar platos, limpiar superficies y manipular objetos húmedos con facilidad y destreza. Perfectos para quienes buscan guantes duraderos, cómodos y resistentes para el hogar.', 3285.00, 20, 18, true, false, 'https://www.abastece.co/abastece/images/3529.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Domestico Azul Calibre 18 Talla L/9 Fuller Pinto', 'guante-domestico-azul-calibre-18-talla-l9-fuller-pinto-4102', 'Guante Doméstico Azul Fuller Pinto (Calibre 18 - Talla L) Protección Versátil y Resistencia para el Aseo Institucional El Guante Doméstico Fuller Pinto en color azul es una herramienta esencial para la protección de manos en labores de limpieza profesional. Su calibre 18 ofrece una resistencia ideal frente a detergentes y humedad, manteniendo la flexibilidad necesaria para tareas de cafetería y servicios generales. El diseño en talla L (9) asegura un ajuste cómodo para manos grandes, mientras que su color azul facilita la codificación por áreas para cumplir con protocolos de bioseguridad y evitar la contaminación cruzada en entornos corporativos.', 82790.00, 20, 39, true, false, 'https://www.abastece.co/abastece/images/4102.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Domestico Rojo Calibre 18 Talla 7 - 7.5', 'guante-domestico-rojo-calibre-18-talla-7-75-72711', 'Guante Doméstico Rojo Calibre 18 Talla 7-7.5 Comodidad y Protección para Tareas de Limpieza en el Hogar El Guante Doméstico Rojo Calibre 18 Talla 7-7.5 está diseñado para brindar una excelente protección durante tareas de limpieza en el hogar. Con un calibre 18, estos guantes son ideales para proteger las manos de productos de limpieza, detergentes y humedad. Su ajuste para la talla 7-7.5 asegura comodidad y destreza durante su uso, permitiendo realizar tareas como lavar platos, limpiar superficies y manipular objetos mojados de forma eficiente. Perfectos para quienes buscan guantes duraderos, cómodos y resistentes para las tareas cotidianas del hogar.', 3543.00, 20, 21, true, false, 'https://www.abastece.co/abastece/images/72711.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Domestico Rojo Calibre 18 Talla 7 - 7.5 Magicbril', 'guante-domestico-rojo-calibre-18-talla-7-75-magicbril-3893', 'Guante Doméstico Rojo Magicbril (Calibre 18 - Talla 7) Protección Ergonómica para Labores de Limpieza y Cafetería El Guante Doméstico Magicbril es la solución ideal para proteger las manos del personal operativo en oficinas y establecimientos comerciales. Su calibre 18 proporciona una excelente resistencia contra la humedad y el contacto directo con detergentes, manteniendo la flexibilidad necesaria para un manejo preciso de utensilios. El color rojo es clave para la implementación de sistemas de limpieza por zonas, ayudando a prevenir la contaminación cruzada. Su diseño ergonómico en talla 7 - 7.5 (S/M) asegura un ajuste perfecto para manos pequeñas o medianas, brindando comodidad y seguridad durante toda la jornada laboral.', 3979.00, 20, 21, true, false, 'https://www.abastece.co/abastece/images/3893.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Domestico Rojo Calibre 18 Talla 8 - 8.5', 'guante-domestico-rojo-calibre-18-talla-8-85-71467', 'Guante Doméstico Rojo Calibre 18 Talla 8-8.5 Protección y Comodidad para Tareas Domésticas y de Limpieza El Guante Doméstico Rojo Calibre 18 Talla 8-8.5 está diseñado para proporcionar una excelente protección durante las tareas domésticas y de limpieza. Con un calibre 18, estos guantes son ideales para proteger las manos contra detergentes, productos de limpieza y humedad. Su ajuste cómodo y preciso para la talla 8-8.5 asegura que puedas realizar tareas como lavar platos, limpiar superficies y manipular objetos mojados con destreza y sin incomodidad. Perfectos para quienes buscan un guante duradero, flexible y resistente para el hogar.', 3489.00, 20, 34, true, false, 'https://www.abastece.co/abastece/images/71467.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Domestico Rojo Calibre 18 Talla 8 - 8.5 Magicbril', 'guante-domestico-rojo-calibre-18-talla-8-85-magicbril-3894', 'Guante Doméstico Rojo Magicbril (Calibre 18 - Talla 8) Protección y Ergonomía para Procesos de Aseo y Desinfección El Guante Doméstico Magicbril es una herramienta de protección esencial para el personal de servicios generales en empresas e instituciones. Su calibre 18 ofrece una resistencia superior contra el contacto prolongado con agua y detergentes, manteniendo la flexibilidad necesaria para un manejo seguro de implementos de limpieza. Su color rojo facilita la estandarización de procesos de higiene por zonas, ayudando a mitigar riesgos de contaminación cruzada. Diseñado en talla 8 - 8.5 (M/L), garantiza un ajuste confortable que optimiza la productividad durante las jornadas de mantenimiento y limpieza de áreas comunes.', 3979.00, 20, 47, true, false, 'https://www.abastece.co/abastece/images/3894.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Especial Calibre 25 Rojo Industrial Latexport Talla 9', 'guante-especial-calibre-25-rojo-industrial-latexport-talla-9-75425', 'Guante Especial Rojo Industrial Latexport (Calibre 25 - Talla 9) Protección Pesada y Resistencia Química para Entornos Industriales El Guante Especial Rojo Industrial de Latexport es un equipo de protección de alto desempeño, diseñado para tareas que exigen una barrera física y química superior. Su calibre 25 proporciona una resistencia excepcional contra pinchazos, desgarros y el contacto con sustancias industriales agresivas. El color rojo vibrante facilita la identificación visual en protocolos de seguridad industrial y manejo de residuos. Con un diseño ergonómico en talla 9, este guante asegura un ajuste firme y cómodo para manos grandes, permitiendo un manejo seguro de maquinaria y herramientas en condiciones de trabajo pesado.', 4578.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/75425.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Multiusos Calibre 18 Verde Talla 8 Fuller Pinto', 'guante-multiusos-calibre-18-verde-talla-8-fuller-pinto-76161', 'Guante Multiusos Verde Fuller Pinto (Calibre 18 - Talla 8) Versatilidad y Resistencia para el Mantenimiento Institucional El Guante Multiusos Fuller Pinto en color verde es la elección ideal para equipos de limpieza profesional que requieren una herramienta adaptable y duradera. Su calibre 18 ofrece una barrera equilibrada que protege contra la humedad y productos químicos de uso común, manteniendo una excelente flexibilidad para tareas de servicios generales. El color verde permite integrar este guante en sistemas de codificación por colores, facilitando la separación de áreas y minimizando riesgos de contaminación. Con un diseño ergonómico en talla 8, garantiza comodidad prolongada y un agarre seguro en superficies húmedas o resbaladizas.', 4709.00, 20, 25, true, false, 'https://www.abastece.co/abastece/images/76161.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante NEGRO Calibre 25 Talla 7- 7.5', 'guante-negro-calibre-25-talla-7-75-3546', 'Guante Industrial Negro Calibre 25 Talla 7-7.5 Protección y Comodidad para el Trabajo en Condiciones Exigentes El Guante Industrial Negro Calibre 25 Talla 7-7.5 es perfecto para trabajos que requieren alta resistencia y comodidad. Fabricado con materiales de alta calidad, este guante ofrece una protección óptima contra abrasiones, cortes y otros riesgos laborales. Su calibre 25 garantiza una excelente durabilidad, mientras que su diseño ergonómico asegura un ajuste perfecto para quienes usan la talla 7-7.5, proporcionando confort durante largos períodos de uso. Ideal para trabajos industriales, construcción, mantenimiento y más, estos guantes ofrecen seguridad sin sacrificar la destreza en las tareas.', 2906.00, 20, 54, true, false, 'https://www.abastece.co/abastece/images/3546.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Negro Calibre 25 Talla 8 - 8.5', 'guante-negro-calibre-25-talla-8-85-3547', 'Guante Industrial Negro Calibre 25 Talla 8-8.5 Resistencia y Comodidad para un Trabajo Seguro y Eficiente El Guante Industrial Negro Calibre 25 Talla 8-8.5 está diseñado para ofrecer una protección superior en entornos de trabajo exigentes. Con un calibre 25, estos guantes proporcionan una gran durabilidad y resistencia a abrasiones, cortes y otros peligros comunes en la industria. Su ajuste perfecto para la talla 8-8.5 asegura comodidad durante su uso prolongado, permitiendo a los trabajadores mantener destreza y precisión sin comprometer la seguridad. Ideales para trabajos en construcción, manufactura, mantenimiento y más, estos guantes son una opción confiable para aquellos que necesitan protección sin sacrificar el confort.', 2800.00, 20, 52, true, false, 'https://www.abastece.co/abastece/images/3547.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Negro Calibre 25 Talla 8 5 Magicbril', 'guante-negro-calibre-25-talla-8-5-magicbril-75942', 'Guante Industrial Negro Magicbril (Calibre 25 - Talla 8.5) Protección Robusta para Mantenimiento Técnico y Aseo Pesado El Guante Industrial Negro de Magicbril es una solución de alto rendimiento diseñada para entornos que demandan una protección superior. Su calibre 25 proporciona una barrera de gran espesor, ideal para resistir el contacto con químicos fuertes, aceites y tareas de abrasión constante. El color negro es especialmente valorado en sectores de mantenimiento y servicios generales, ya que disimula el desgaste y la suciedad en jornadas intensivas. Gracias a su horma en talla 8.5, ofrece un ajuste cómodo y seguro, garantizando que el personal mantenga la destreza necesaria sin comprometer la seguridad de sus manos.', 3840.00, 20, 23, true, false, 'https://www.abastece.co/abastece/images/75942.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Negro Calibre 25 Talla 9 - 9.5', 'guante-negro-calibre-25-talla-9-95-3548', 'Guante Industrial Negro Calibre 25 Talla 9-9.5 Máxima Protección y Confort para Tareas Exigentes El Guante Industrial Negro Calibre 25 Talla 9-9.5 ofrece una excelente combinación de resistencia y comodidad para trabajos que requieren un alto nivel de protección. Fabricado con materiales de alta calidad, este guante tiene un calibre 25 que lo hace ideal para resistir abrasiones, cortes y otros riesgos comunes en ambientes industriales. Su diseño ergonómico, adaptado a la talla 9-9.5, proporciona un ajuste cómodo y seguro, permitiendo al usuario realizar tareas con precisión y sin incomodidad. Perfecto para trabajos en construcción, mantenimiento, manufactura y más, este guante asegura durabilidad y seguridad durante su uso prolongado.', 2800.00, 20, 31, true, false, 'https://www.abastece.co/abastece/images/3548.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Guante Rojo (Manejo Residuos Biologicos) Calibre 25 Talla 8 - 8.5', 'guante-rojo-manejo-residuos-biologicos-calibre-25-talla-8-85-3541', 'Guante Industrial Rojo Calibre 25 Talla 8-8.5 Resistencia y Confort para Trabajo Pesado El Guante Industrial Rojo Calibre 25 Talla 8-8.5 estÃƒ¡ diseÃƒÂ±ado para ofrecer una proteccion confiable y duradera en tareas industriales que requieren alta resistencia. Con un calibre 25, estos guantes brindan una proteccion optima contra abrasiones y cortes, siendo ideales para trabajos de construccion, manufactura, mantenimiento y otros entornos de alto riesgo. Su ajuste comodo y ergonomico para la talla 8-8.5 asegura que el trabajador pueda realizar sus tareas con destreza y sin incomodidad, manteniendo la seguridad en todo momento. Perfectos para quienes buscan un guante fuerte, flexible y comodo durante largas jornadas de trabajo.', 3862.00, 20, 50, true, false, 'https://www.abastece.co/abastece/images/3541.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Haragan Escurridor Metalico Para Piso 1 Mt Con Mango 1.60 Cm', 'haragan-escurridor-metalico-para-piso-1-mt-con-mango-160-cm-76383', 'Haragán Escurridor Metálico para Piso (1 Metro) con Mango Eficiencia Industrial para el Secado de Grandes Superficies El Haragán Escurridor Metálico de 1 metro es la herramienta definitiva para la gestión de líquidos en áreas extensas como bodegas, plantas de producción, parqueaderos y centros logísticos. Su estructura metálica reforzada garantiza una durabilidad superior frente al uso rudo, mientras que su goma de alta densidad se adapta a diversas irregularidades del piso, asegurando un secado impecable en menos pasadas. Equipado con un mango ergonómico de 1.60 metros, este escurridor industrial permite una postura de trabajo óptima, maximizando la productividad del personal de servicios generales y reduciendo el esfuerzo físico en jornadas de limpieza intensiva.', 63386.00, 20, 31, true, false, 'https://www.abastece.co/abastece/images/76383.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Haragan Escurridor Metalico Para Piso 80 Cm', 'haragan-escurridor-metalico-para-piso-80-cm-74579', 'Haragán Escurridor Metálico para Piso (1 Metro) con Mango Eficiencia Industrial para el Secado de Grandes Superficies El Haragán Escurridor Metálico de 1 metro es la herramienta definitiva para la gestión de líquidos en áreas extensas como bodegas, plantas de producción, parqueaderos y centros logísticos. Su estructura metálica reforzada garantiza una durabilidad superior frente al uso rudo, mientras que su goma de alta densidad se adapta a diversas irregularidades del piso, asegurando un secado impecable en menos pasadas.', 69372.00, 20, 48, true, false, 'https://www.abastece.co/abastece/images/74579.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Hipoclorito De Calcio Granulado 1 Kg', 'hipoclorito-de-calcio-granulado-1-kg-75909', 'Hipoclorito de Calcio Granulado (1 Kg) Desinfectante Potente para Tratamiento de Aguas y Superficies Industriales El Hipoclorito de Calcio Granulado es un agente desinfectante de alta eficacia, ampliamente utilizado para la purificación de agua y el mantenimiento de condiciones higiénicas en entornos industriales y recreativos. Su presentación granular permite una disolución controlada, lo que lo hace ideal para el tratamiento de piscinas, tanques de almacenamiento y sistemas de agua potable, eliminando de manera efectiva bacterias, algas y microorganismos. Gracias a su estabilidad y alta concentración de cloro activo, es una herramienta indispensable para garantizar la bioseguridad en procesos de saneamiento ambiental y desinfección profunda de superficies resistentes.', 14935.00, 20, 20, true, false, 'https://www.abastece.co/abastece/images/75909.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Hipoclorito De Sodio Al 13% Galon 3800 Ml Berhlan', 'hipoclorito-de-sodio-al-13-galon-3800-ml-berhlan-3916', 'Hipoclorito de Sodio al 13% Berhlan (Galón x 3800 ml) Poder Desinfectante de Concentración Industrial para Ambientes Corporativos El Hipoclorito de Sodio al 13% de Berhlan en presentación de galón es una solución potente y versátil para el mantenimiento de altos estándares de higiene en oficinas, centros educativos y áreas industriales. Gracias a su alta concentración, este desinfectante líquido permite una dilución eficaz para el blanqueamiento de textiles, la eliminación de microorganismos en superficies de alto contacto y la desinfección profunda de baños y cocinas. Su formato de 3.8 litros es ideal para facilitar el almacenamiento y la dosificación precisa, garantizando una protección biológica superior y un rendimiento costo-beneficio óptimo para el abastecimiento institucional.', 12070.00, 20, 41, true, false, 'https://www.abastece.co/abastece/images/3916.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Insecticida Raid Aerosol Cucaracha X2 400ml', 'insecticida-raid-aerosol-cucaracha-x2-400ml-73789', 'Insecticida Raid Aerosol Mata Cucarachas (Dúo Pack 2 x 400 ml) Control de Plagas de Acción Inmediata para Ambientes Corporativos El Insecticida Raid Aerosol en su presentación especializada para cucarachas es una herramienta esencial para el mantenimiento sanitario en cafeterías, bodegas, oficinas y áreas comunes. Su fórmula de doble acción elimina los insectos al contacto y continúa actuando por semanas, creando una barrera protectora que evita nuevas infestaciones. Este práctico Dúo Pack de 400 ml cada uno asegura un suministro constante para el control de plagas rastreras, garantizando entornos de trabajo limpios y seguros. Su aplicación es sencilla y directa, permitiendo llegar a grietas y rincones difíciles donde suelen ocultarse estos insectos, manteniendo la integridad higiénica de sus instalaciones.', 35808.00, 20, 53, true, false, 'https://www.abastece.co/abastece/images/73789.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Insecticida Raid Aerosol Elimina Voladores 400ml', 'insecticida-raid-aerosol-elimina-voladores-400ml-2111', 'Raid Aerosol x 400 ml: Proteccion Efectiva contra los Voladores Elimina Moscas, Mosquitos y Otros Insectos Voladores Marca Raid: Calidad y Confianza en cada Aplicacion El Raid Aerosol x 400 ml es tu aliado para protegerte de los insectos voladores. Con su formula efectiva, este aerosol elimina moscas, mosquitos y otros insectos molestos, manteniendo tu hogar libre de plagas. Confia en la marca Raid, reconocida por su calidad y confianza en productos de control de plagas. Este aerosol ofrece una proteccion eficaz, permitiendote disfrutar de un ambiente libre de insectos voladores.', 16019.00, 20, 29, true, false, 'https://www.abastece.co/abastece/images/2111.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Insecticida Raid Unidad Electrica 45 Noches + Repuesto', 'insecticida-raid-unidad-electrica-45-noches-repuesto-74744', 'Kit Insecticida Raid Unidad Eléctrica (Aparato + Repuesto 45 Noches) Sistema Integral de Protección Continua para Entornos Profesionales El Kit Raid Unidad Eléctrica es la solución completa para establecer una barrera protectora contra mosquitos y zancudos en áreas de trabajo, recepciones y salas de juntas. Este sistema incluye el dispositivo difusor y un repuesto líquido de 45 noches, diseñado para ofrecer una defensa constante y silenciosa sin la necesidad de aplicaciones manuales. Su tecnología permite una liberación gradual y uniforme del insecticida, garantizando un ambiente confortable y libre de plagas voladoras, incluso en espacios con ventilación moderada. Es un componente esencial para el plan de saneamiento y bienestar de cualquier instalación corporativa que busque eficiencia y discreción.', 19569.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/74744.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Jabon Coco Varela En Barra 300gr.', 'jabon-coco-varela-en-barra-300gr-73042', 'Jabón de Coco Varela en Barra (300g) Limpieza Tradicional y Cuidado Superior para Prendas Delicadas El Jabón de Coco Varela es un referente en el mercado colombiano por su eficacia y suavidad en el lavado de textiles. Esta presentación en barra de 300 gramos es ideal para el tratamiento de manchas difíciles y el cuidado de prendas delicadas que requieren un lavado manual. Gracias a sus componentes derivados del aceite de coco, este jabón genera una espuma cremosa que remueve la suciedad profundamente sin maltratar las fibras ni irritar las manos del personal de servicios generales. Es un insumo indispensable en áreas de lavandería institucional, hoteles y servicios de limpieza profesional que priorizan la durabilidad de la lencería y la eficiencia en el lavado.', 3788.00, 20, 23, true, false, 'https://www.abastece.co/abastece/images/73042.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Jabon FAB En Barra Ultra Flash Floral 300 Gr', 'jabon-fab-en-barra-ultra-flash-floral-300-gr-74887', 'Jabón FAB en Barra Ultra Flash Floral (300 Gr) Limpieza Instantánea y Fragancia Prolongada para el Lavado Institucional El Jabón FAB en Barra Ultra Flash Floral es una solución de alto rendimiento diseñada para remover las manchas más difíciles en una sola pasada. Su fórmula avanzada &quot;Ultra Flash&quot; actúa rápidamente sobre la suciedad, reduciendo el tiempo de restregado y optimizando las labores de lavandería en entornos profesionales como hoteles, restaurantes y centros de salud. Esta barra de 300 gramos no solo garantiza una limpieza profunda en cuellos, puños y textiles delicados, sino que también deja una agradable y fresca fragancia floral que perdura en las prendas. Es el aliado perfecto para el personal de servicios generales que busca resultados impecables con el menor esfuerzo.', 2767.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/74887.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Jabon Liquido Azul Orion 20 Litros', 'jabon-liquido-azul-orion-20-litros-75036', 'Jabón Líquido Azul Orion (Garrafa x 20 Litros) Detergente Multiusos de Alto Rendimiento para Lavado Industrial El Jabón Líquido Azul Orion es una solución de limpieza robusta y versátil, diseñada específicamente para satisfacer las demandas de alto consumo en entornos industriales y comerciales. Su fórmula balanceada permite una remoción efectiva de la suciedad en una amplia variedad de superficies, desde pisos y paredes hasta textiles, convirtiéndose en un aliado indispensable para el mantenimiento de plantas de producción, bodegas y grandes instalaciones. Esta presentación en garrafa de 20 litros garantiza un suministro prolongado y optimiza los costos operativos, facilitando la gestión de inventarios en el área de servicios generales. Su color azul característico y su capacidad espumante aseguran una limpieza profunda y un acabado impecable en cada aplicación.', 102373.00, 20, 47, true, false, 'https://www.abastece.co/abastece/images/75036.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Jabon Liquido Azul Orion 3750 Ml', 'jabon-liquido-azul-orion-3750-ml-73102', 'Jabón Líquido Azul Orion 3750 ml: Limpieza Efectiva para el Hogar Tu Aliado en la Higiene y el Cuidado de la Piel El Jabón Líquido Azul Orion de 3750 ml es la solución perfecta para mantener la limpieza y frescura en tu hogar. Su fórmula suave y efectiva no solo elimina la suciedad, sino que también cuida la piel, dejándola hidratada y protegida. Ideal para el uso diario, este jabón es perfecto para manos, cuerpo y cualquier área que requiera una limpieza profunda sin irritaciones. ¡Descubre la calidad y el aroma que transformarán tu rutina de limpieza!', 22509.00, 20, 32, true, false, 'https://www.abastece.co/abastece/images/73102.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Jabon Liquido Berhlan Azul 3800ml', 'jabon-liquido-berhlan-azul-3800ml-3917', 'Jabón Líquido Azul Berhlan (Galón x 3800 ml) Limpieza Eficiente y Multiusos para el Mantenimiento Institucional El Jabón Líquido Azul de Berhlan en su práctica presentación de galón es un aliado fundamental para las rutinas de limpieza en empresas, colegios y establecimientos comerciales. Formulado para ofrecer una alta capacidad de remoción de suciedad en diversas superficies, este detergente líquido destaca por su versatilidad, permitiendo su uso tanto en el lavado de textiles como en la limpieza de pisos y áreas comunes. Su consistencia y poder espumante aseguran un rendimiento óptimo, facilitando las tareas del personal de servicios generales al proporcionar resultados impecables con una fragancia limpia y fresca. Al ser un producto de 3.8 litros, representa una solución económica y de alto desempeño para el abastecimiento de suministros de aseo corporativo.', 15535.00, 20, 16, true, false, 'https://www.abastece.co/abastece/images/3917.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Jabon Liquido Berhlan Para Manos Neutro 3800ml', 'jabon-liquido-berhlan-para-manos-neutro-3800ml-77176', 'Jabón Líquido para Manos Neutro Berhlan 3800 ml · Galón Higiene estandarizada para alto consumo y continuidad operativa Jabón líquido formulado con pH neutro, desarrollado para la limpieza frecuente de manos sin generar resequedad. Presentado en un envase de 3800 ml, optimiza el rendimiento en puntos de alto tránsito y reduce la frecuencia de reposición. Su textura fluida facilita la dosificación en dispensadores estándar, contribuyendo a una operación ordenada y a la continuidad operativa de protocolos de higiene. Como insumo estratégico, permite la estandarización del consumo, mejora la eficiencia logística y promueve condiciones constantes de higiene que favorecen el bienestar del equipo y la gestión sostenible de inventarios.', 16470.00, 20, 39, true, false, 'https://www.abastece.co/abastece/images/77176.jpg'),
('c4444444-4444-4444-4444-444444444444', 'Jabón Liquido Corporal Hotelero 4000ml Amatic', 'jabon-liquido-corporal-hotelero-4000ml-amatic-4136', 'Jabón Líquido Corporal Hotelero 4000 ml Amatic ¡Fórmula dermatológica enriquecida con agentes humectantes, pH balanceado para baño corporal diario y garrafa institucional de 4000 ml (4 Litros)! Asegure una experiencia de confort, frescura y cuidado dermatológico superior en las duchas corporativas, habitaciones de hotel, gimnasios y vestieres de su organización con el Jabón Líquido Corporal Línea Hotelera de Amatic en formato garrafa de 4000 ml (4 Litros). Especialmente formulado para la limpieza integral del cuerpo en entornos de alta exigencia institucional, este jabón corporal combina tensioactivos suaves de alto poder espumante con ingredientes humectantes que remueven con delicadeza la suciedad y las impurezas del cuerpo sin resecar la piel ni alterar su barrera cutánea natural. Su fórmula con pH balanceado y delicada fragancia aromática deja una sensación refrescante y aterciopelada tras cada baño, siendo ideal para el uso diario de huéspedes, atletas y colaboradores. Su presentación a granel en garrafa de 4 Litros optimiza los costos operativos de recarga continua en dispensadores corporales de pared en cadenas hoteleras, clubes deportivos, casinos de personal y centros de spa. ¡Eleve el estándar de bienestar de sus instalaciones con productos de aseo corporal de alta rentabilidad y desempeño!', 49775.00, 20, 42, true, false, 'https://www.abastece.co/abastece/images/4136.jpg'),
